// ---------------------------------------------------------------------------
// Secours : une espèce encore sans fiche reçoit un dessin de sa famille, déformé d'après son identifiant
// pour ne jamais copier un dessin existant. Ce n'est qu'un filet : la bonne réponse est d'ajouter une fiche.
// ---------------------------------------------------------------------------

export function specOf(sp: Species): ArtSpec {
  const own = SPECS[sp.id];
  if (own) return own;
  const s = seedOf(sp.id), j = (n: number, k: number): number => ((s >> k) % (n * 2 + 1)) - n;
  switch (sp.shape) {
    case 'ray': case 'flat':
      return { r: 'ray', Ld: 28 + j(3, 0), W: 18 + j(4, 3), f: 0.45 + j(2, 6) * 0.05, a: 0.8 + j(2, 9) * 0.15, b: 1 + j(2, 12) * 0.15, tail: [14 + j(4, 2), 'whip'], pat: [['spots', 7 + (s % 5), 3]] };
    case 'octo': return { r: 'ceph', kind: 'octo', ML: 15 + j(2, 0), MH: 8 + j(1, 3), arms: [8, 20 + j(4, 6), 1.2, 1.5] };
    case 'squid': return { r: 'ceph', kind: 'squid', ML: 27 + j(3, 0), MH: 5.5 + j(1, 3) * 0.5, fin: [0.4, 5 + j(1, 6), 'tri'], arms: [5, 10 + j(2, 9), 1.2, 1.3], tent: [17 + j(3, 12), 2] };
    case 'crab': return { r: 'crab', cw: 10 + j(2, 0), ch: 7 + j(1, 3), form: (['oval', 'box', 'hex', 'shield', 'round'] as const)[s % 5], legs: [9 + j(2, 6), 1], claw: [5 + j(1, 9), 5 + j(1, 12)] };
    case 'shrimp': return { r: 'crust', L: 30 + j(3, 0), th: 4 + j(1, 3) * 0.4, curl: 1 + j(2, 6) * 0.1, rostrum: -6 + j(2, 9), ant: [18 + j(3, 12), 7] };
    case 'shell': return { r: 'shell', form: (['clam', 'cockle', 'mussel', 'oyster', 'scallop', 'spiral'] as const)[s % 6], w: 12 + j(2, 0), h: 9 + j(2, 3), ribs: 5 + (s % 4) };
    case 'seahorse': return { r: 'horse', H: 36 + j(3, 0) };
    case 'eel': case 'serpent':
      return { L: 58 + j(6, 0), T: 3.6 + j(2, 3) * 0.3, B: 3.6 + j(2, 3) * 0.3, pk: 0.08, nose: 0.5, ped: 0.6, tp: 0.7, wave: [4 + j(1, 6), 34 + j(4, 9)], tail: ['point', 4, 1.5], d: [F(0.18, 1, 2 + (s % 2), 'low')], gill: 0 };
    case 'shark':
      return { L: 54 + j(4, 0), T: 6.5 + j(2, 3) * 0.4, B: 6.2, pk: 0.32, nose: 0.9, noseB: 0.6, tail: ['shark', 12 + j(1, 6), 13], tc: 0, d: [F(0.36, 0.5, 8 + j(1, 9), 'falc', { lean: 0.35, c: 0 })], pec: ['low', 0.3, 11 + j(2, 12), 0], gill: 5, mouth: ['down', 4], bl: 0.2 };
    case 'whale':
      return { L: 66 + j(4, 0), T: 10 + j(1, 3), B: 9.5, pk: 0.3, nose: 0.45, tail: ['fluke', 9, 10 + j(1, 6)], tc: 0, pec: ['paddle', 0.26, 9 + j(1, 9), 0], gill: 0, bl: 0.45 };
    default: {
      const deep = sp.shape === 'deep' || sp.shape === 'moon' || sp.shape === 'angler';
      return {
        L: (deep ? 28 : 36) + j(4, 0), T: (deep ? 9 : 5.5) + j(2, 3) * 0.5, B: (deep ? 9 : 5.8) + j(2, 6) * 0.5, pk: 0.36 + j(2, 9) * 0.02,
        tail: [(['fork', 'trunc', 'round', 'lunate'] as const)[s % 4], 7 + j(1, 12), 7 + j(1, 14)],
        d: [F(0.3 + j(2, 2) * 0.02, 0.6 + j(2, 5) * 0.03, 4 + (s % 3))], an: [F(0.62, 0.78, 3)], pel: [0.4, 4], pec: ['in', 0.27, 5],
        bill: sp.shape === 'bill' ? [12 + j(2, 7), 0, 1] : undefined,
      };
    }
  }
}
